func servings(_ input: String?) -> Int {
    guard let input, let quantity = Int(input), (1...12).contains(quantity) else {
        return 1
    }
    return quantity
}

print(servings("4"))
print(servings("oops"))
print(servings(nil))

let drinks = ["tea", "coffee", "tea"]
var counts: [String: Int] = [:]
for drink in drinks {
    counts[drink, default: 0] += 1
}

for drink in counts.keys.sorted() {
    print("\(drink): \(counts[drink, default: 0])")
}

struct Basket {
    var items: Int

    mutating func add(_ count: Int) {
        items += count
    }
}

let original = Basket(items: 2)
var edited = original
edited.add(3)
print(original.items)
print(edited.items)

enum OvenError: Error {
    case invalidTemperature
}

func temperature(from text: String) throws -> Int {
    guard let degrees = Int(text), (100...250).contains(degrees) else {
        throw OvenError.invalidTemperature
    }
    return degrees
}

for input in ["200", "70"] {
    do {
        let degrees = try temperature(from: input)
        print("oven: \(degrees)")
    } catch OvenError.invalidTemperature {
        print("temperature out of range")
    } catch {
        print("unexpected oven error")
    }
}
